.bcn-release-stream {
  display: flex;
  flex-direction: column;
}
.bcn-release {
  max-inline-size: 46rem;
  margin-inline: auto;
  inline-size: 100%;
  scroll-margin-top: var(--spacing-500);
  padding-block: var(--spacing-800);
}
.bcn-release:first-child {
  padding-block-start: var(--spacing-500);
}
.bcn-release__header {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-150);
  margin-block-end: var(--spacing-600);
}
.bcn-release__meta {
  margin: 0;
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  font-size: 0.875rem;
  line-height: 1.4;
  color: var(--color-text-tertiary);
}
.bcn-release__latest {
  font-weight: var(--font-weight-medium);
  color: var(--color-text-secondary);
}
.bcn-release__latest:after {
  content: "·";
  margin-inline: var(--spacing-200);
  color: var(--color-text-muted);
}
.bcn-release__version {
  margin: 0;
  font-family: var(--font-decorative);
  font-size: var(--type-size-600);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.01em;
  color: var(--color-text-primary);
}
.bcn-release__headlines {
  list-style: none;
  margin: 0 0 var(--spacing-700);
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-600);
}
.bcn-release__headline {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-200);
}
.bcn-release__headline-title {
  margin: 0;
  font-family: var(--font-decorative);
  font-size: clamp(1.1875rem, 1.05rem + 0.7vw, 1.3125rem);
  font-weight: 500;
  line-height: 1.3;
  letter-spacing: -0.005em;
  color: var(--color-text-primary);
}
.bcn-release__headline-link {
  color: inherit;
  text-decoration: none;
}
.bcn-release__headline-text {
  margin: 0;
  max-inline-size: 42rem;
  font-size: 1rem;
  line-height: var(--line-height-normal);
  color: var(--color-text-secondary);
}
.bcn-release strong {
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
}
.bcn-release code {
  font-family: var(--font-mono);
  font-size: 0.875em;
  padding: 1px 5px;
  border-radius: var(--radius-100);
  background: var(--color-surface-sunken);
  color: var(--color-text-primary);
}
.bcn-release__group-title {
  margin: 0 0 var(--spacing-400);
  padding-block-end: var(--spacing-200);
  border-bottom: 1px solid var(--color-border-light);
  font-size: 1.0625rem;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-secondary);
}
.bcn-release__entries {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-500);
}
.bcn-release__entry {
  scroll-margin-top: var(--spacing-500);
}
.bcn-release__entry-head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: var(--spacing-150) var(--spacing-300);
  margin-block-end: var(--spacing-300);
  max-inline-size: 42rem;
}
.bcn-release__entry-title {
  margin: 0;
  font-size: 1rem;
  font-weight: var(--font-weight-semibold);
  line-height: 1.4;
  color: var(--color-text-primary);
}
.bcn-release__blocks {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-400);
  max-inline-size: 42rem;
}
.bcn-release__callout {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: start;
  gap: var(--spacing-300);
  padding: var(--spacing-400);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-200);
  background: var(--color-surface-sunken);
}
.bcn-release__callout-icon {
  display: inline-flex;
  margin-block-start: 2px;
  color: var(--color-text-secondary);
}
.bcn-release__callout-text {
  margin: 0;
  font-size: 1rem;
  line-height: var(--line-height-normal);
  color: var(--color-text-primary);
}
.bcn-release__p {
  margin: 0;
  font-size: 1rem;
  line-height: var(--line-height-normal);
  color: var(--color-text-primary);
}
.bcn-release__group + .bcn-release__group {
  margin-block-start: var(--spacing-700);
}
.bcn-release__applies {
  font-size: 0.8125rem;
  color: var(--color-text-tertiary);
}
.bcn-release__flag {
  display: inline-flex;
  align-items: baseline;
  gap: var(--spacing-100);
  padding: 2px var(--spacing-200);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  background: var(--color-surface);
  font-size: 0.8125rem;
  color: var(--color-text-tertiary);
}
.bcn-release__flag code {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
}
.bcn-release__bullets {
  margin: 0;
  padding-inline-start: var(--spacing-500);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-200);
}
.bcn-release__bullet {
  font-size: 1rem;
  line-height: var(--line-height-normal);
  color: var(--color-text-primary);
}
.bcn-release__bullet::marker {
  color: var(--color-text-tertiary);
}
.bcn-release__fixes {
  margin-block-start: var(--spacing-600);
}
.bcn-release__fixes-summary {
  cursor: pointer;
  font-size: 0.9375rem;
  font-weight: var(--font-weight-medium);
  color: var(--color-text-secondary);
  list-style-position: inside;
}
.bcn-release + .bcn-release {
  border-top: 1px solid var(--color-border-light);
}
.bcn-search-trigger .esa-icon {
  flex: none;
  color: var(--color-text-tertiary);
}
.topbar__right .esa-icon-button {
  color: var(--color-text-secondary);
}
.project-switcher__trigger > .esa-icon:first-child {
  flex-shrink: 0;
  color: var(--bcn-gray-500);
}
.nav-section__header > .esa-icon:first-child {
  flex-shrink: 0;
  color: var(--bcn-gray-950);
  transition: color 0.15s ease;
}
.nav-section__header > .esa-icon:last-child {
  color: var(--bcn-gray-400);
  transition:
    transform 0.15s ease,
    opacity 0.2s ease-in-out;
  flex-shrink: 0;
}
.bcn-help-bar .esa-icon-button {
  color: var(--bcn-helpbar-fg-muted);
  --icon-button-bg-hover: var(--bcn-helpbar-hover-bg);
}
.bcn-gd__label .esa-icon {
  color: var(--color-text-tertiary);
  flex: none;
}
.esa-icon {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_icon-size);
  height: var(--_icon-size);
  line-height: 1;
  color: inherit;
}
.esa-icon--xs {
  --_icon-size: var(--icon-size-xs, 14px);
}
.esa-icon svg {
  display: block;
  width: var(--_icon-size);
  height: var(--_icon-size);
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, var(--icon-size-small, 16px));
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
}
.esa-icon-button {
  --_ib-size: var(--form-height-md, 40px);
  --_ib-bg-hover: var(
    --icon-button-bg-hover,
    color-mix(in srgb, currentColor 14%, transparent)
  );
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_ib-size);
  height: var(--_ib-size);
  padding: 0;
  border: 0;
  border-radius: var(--radius-200, 8px);
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition: background var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
}
.page-layout__title h1 .esa-icon {
  color: var(--bcn-gray-1000);
  flex-shrink: 0;
}

.bcn-release__entry {
  scroll-margin-top: var(--spacing-500);
}
.bcn-release__entry-head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: var(--spacing-150) var(--spacing-300);
  margin-block-end: var(--spacing-300);
  max-inline-size: 42rem;
}
.bcn-release__entry-title {
  margin: 0;
