  display: flex;
  flex-direction: column;
  gap: var(--spacing-400);
  max-inline-size: 42rem;
}
.bcn-release__p {
  margin: 0;
  font-size: 1rem;
  line-height: var(--line-height-normal);
  color: var(--color-text-primary);
}
.bcn-release__flag {
  display: inline-flex;
